// Verifies compatibility with hashes created by Werkzeug (the Flask app).
// The fixtures below were generated by the real werkzeug.security.generate_password_hash.
import test from "node:test";
import assert from "node:assert/strict";
import { hashPassword, verifyPassword } from "../src/lib/password.ts";
import fixtures from "./werkzeug-fixtures.json" with { type: "json" };

test("verifies Werkzeug scrypt hashes", () => {
  assert.ok(verifyPassword(fixtures.scrypt, fixtures.password));
  assert.ok(!verifyPassword(fixtures.scrypt, fixtures.password + "x"));
});

test("verifies Werkzeug pbkdf2 hashes", () => {
  assert.ok(verifyPassword(fixtures.pbkdf2, fixtures.password));
  assert.ok(!verifyPassword(fixtures.pbkdf2, "nope"));
});

test("hashes round-trip and use the Werkzeug scrypt format", () => {
  const h = hashPassword("s3cret-ü-密码");
  assert.match(h, /^scrypt:32768:8:1\$[A-Za-z0-9]{16}\$[0-9a-f]{128}$/);
  assert.ok(verifyPassword(h, "s3cret-ü-密码"));
  assert.ok(!verifyPassword(h, "other"));
});

test("garbage hashes never verify", () => {
  for (const bad of ["", "x", "a$b", "md5$a$b", null, undefined]) {
    assert.ok(!verifyPassword(bad as string, "x"));
  }
});
